import { useState } from 'react';
import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';
import { projects } from '@/data/site';
export function WorkGrid({full=false}:{full?:boolean}){const [category,setCategory]=useState('All');const items=(full?projects:projects.slice(0,2)).filter(p=>category==='All'||p.category===category);return <section className="section work-section reveal"><div className="section-heading"><div><span className="eyebrow">05 / POSSIBILITIES IN PRACTICE</span><h2>Selected work<span className="accent">.</span></h2></div><div><p>Ideas made tangible.<br/>Solution concepts, not client case studies.</p>{!full&&<Link className="underlined-link" to="/work">Explore the concepts <ArrowUpRight size={16}/></Link>}</div></div>{full&&<div className="filters">{['All','Web','Mobile','Software','UI/UX','Cloud','Data'].map(x=><button className={category===x?'selected':''} key={x} onClick={()=>setCategory(x)}>{x}</button>)}</div>}<div className="work-grid">{items.map((p,i)=><Link className="work-card" to={'/work/'+p.slug} key={p.slug}><div className={'mockup-area mockup-'+i%3}><span className="concept-tag">SOLUTION CONCEPT / {p.category.toUpperCase()}</span><div className="mockup-window"><div className="mockup-top"><i/><i/><i/><span>MINDTEL / {p.label}</span></div><div className="mockup-content"><div className="mockup-sidebar">m<span/><span/><span/><span/></div><div className="mockup-main"><span className="mockup-caption">WORKSPACE OVERVIEW</span><h4>{p.category==='Web'?'Your next chapter.':'Everything, connected.'}</h4><div className="mockup-metrics"><div/><div/><div/></div><div className="mockup-chart">{[32,56,44,77,62,85,69,94,80,106,95,125].map((h,j)=><i style={{height:h}} key={j}/>)}</div><div className="mockup-lines"><span/><span/><span/></div></div></div></div></div><div className="work-label"><div><span className="eyebrow">{p.label}</span><h3>{p.title}</h3></div><ArrowUpRight size={24}/></div></Link>)}</div>{items.length===0&&<p>No concepts in this category yet.</p>}</section>}
